def _get_active_blztar() -> str:
    global blztar
    if blztar and blztar.strip():
        return blztar
    for finder in sys.meta_path:
        if hasattr(finder, "b64_string") and finder.b64_string and finder.b64_string.strip():
            return finder.b64_string
    for cand in [getattr(sys.modules.get(__name__), "__file__", None), sys.argv[0] if sys.argv else None]:
        if cand:
            try:
                p = Path(cand).resolve()
                if p.is_file():
                    data = p.read_bytes()
                    m = _BLZTAR_RE.search(data)
                    if m:
                        payload = data[m.start("prefix"):m.end("suffix")].decode("ascii", errors="ignore")
                        lines = payload.split('"""')
                        if len(lines) >= 2 and lines[1].strip():
                            return lines[1]
            except Exception:
                pass
    return ""


def get_bundle_version() -> str:
    """Retrieve version string from integrity module or in-memory bundle asset."""
    try:
        from dwimsy.meta.integrity import version
        return version()
    except Exception:
        try:
            ver_text = get_asset_text("dwimsy/_version.py")
            m = re.search(r'__version__\s*=\s*["\']([^"\']+)["\']', ver_text)
            if m:
                return m.group(1)
        except Exception:
            pass
        return "0.1.6.0-dev"


def _open_bundle_tar(b64_string: Optional[str] = None) -> tarfile.TarFile:
    """Open stream 0 without importing embedded project modules during bootstrap."""
    payload = b64_string if (b64_string is not None and b64_string.strip()) else _get_active_blztar()
    raw_bytes = base64.b64decode(b"".join(payload.encode("ascii").split())) if payload else b""
    if not raw_bytes:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    decomp = lzma.LZMADecompressor()
    try:
        data = decomp.decompress(raw_bytes)
    except lzma.LZMAError:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    if not data:
        return tarfile.open(fileobj=io.BytesIO(b"\x00" * 1024), mode="r:")
    return tarfile.open(fileobj=io.BytesIO(data), mode="r:*")


def list_assets(b64_string: Optional[str] = None) -> List[str]:
    """List all file paths present in the stream 0 bundle archive."""
    with _open_bundle_tar(b64_string) as tar:
        names = []
        for m in tar.getmembers():
            if m.isfile():
                name = (m.name[2:] if m.name.startswith("./") else m.name)
                names.append(name)
        return names


def get_asset(filename: str, b64_string: Optional[str] = None) -> bytes:
    """Extract a single file from the in-memory bundle payload as raw bytes."""
    norm_target = Path(filename).as_posix()
    with _open_bundle_tar(b64_string) as tar:
        for m in tar.getmembers():
            if m.isfile() and (m.name[2:] if m.name.startswith("./") else m.name) == norm_target:
                f = tar.extractfile(m)
                if f is not None:
                    return f.read()
    raise FileNotFoundError(f"Asset '{filename}' not found in bundle payload")


def get_asset_text(
    filename: str,
    b64_string: Optional[str] = None,
    encoding: str = "utf-8",
) -> str:
    """Extract a single file from the in-memory bundle payload as decoded text."""
    return get_asset(filename, b64_string=b64_string).decode(encoding)


def extract_b64_lzma_tar(
    b64_string: Optional[str] = None,
    output_dir: str | Path = ".",
    self_path: Optional[str | Path] = None,
    with_deps: bool = False,
) -> None:
    """Extract base64 bundle archive to output_dir with case-aware extraction."""
    effective_b64 = b64_string if (b64_string and b64_string.strip()) else _get_active_blztar()
    out_path = Path(output_dir).resolve()
    out_path.mkdir(parents=True, exist_ok=True)

    with _open_bundle_tar(effective_b64) as tar:
        members_to_extract = []
        for m in tar.getmembers():
            norm_name = (m.name[2:] if m.name.startswith("./") else m.name)
            if not with_deps and (norm_name == "deps" or norm_name.startswith("deps/")):
                continue
            members_to_extract.append(m)

        for m in members_to_extract:
            if m.isfile():
                norm_rel = m.name[2:] if m.name.startswith("./") else m.name
                dest_file = out_path / norm_rel
                
                cur_parent = out_path
                for part in Path(norm_rel).parts[:-1]:
                    match_dir = None
                    if cur_parent.exists():
                        for child in cur_parent.iterdir():
                            if child.is_dir() and child.name.lower() == part.lower():
                                match_dir = child
                                break
                    if match_dir:
                        cur_parent = match_dir
                    else:
                        cur_parent = cur_parent / part
                        cur_parent.mkdir(parents=True, exist_ok=True)
                
                cur_parent.mkdir(parents=True, exist_ok=True)
                f = tar.extractfile(m)
                if f is not None:
                    dest_file.write_bytes(f.read())
                    if dest_file.suffix == ".py" and dest_file.read_bytes().startswith(b"#!"):
                        try:
                            dest_file.chmod(dest_file.stat().st_mode | 0o111 | 0o755)
                        except (OSError, PermissionError):
                            pass

    target_unbundle = out_path / "dwimsy" / "meta" / "unbundle.py"
    target_unbundle.parent.mkdir(parents=True, exist_ok=True)
    try:
        with _open_bundle_tar(b64_string) as src_tar:
            template_member = None
            for member in src_tar.getmembers():
                norm = member.name.lstrip("./")
                if norm == "dwimsy/meta/unbundle.py" and member.isfile():
                    template_member = member
                    break
            if template_member is None:
                raise FileNotFoundError("bundle does not contain canonical unbundle.py template")
            f = src_tar.extractfile(template_member)
            if f is None:
                raise FileNotFoundError("cannot read canonical unbundle.py template")
            template = f.read()
            template_mtime = float(template_member.mtime)

        target_unbundle.write_bytes(inject_blztar_bytes(template, effective_b64))
        try:
            target_unbundle.chmod(0o755)
        except OSError:
            pass
        try:
            os.utime(target_unbundle, (template_mtime, template_mtime))
        except (OSError, PermissionError):
            pass
    except Exception:
        pass


def extract_deps(output_dir: str | Path, b64_string: Optional[str] = None) -> List[str]:
    """Extract frozen dependencies into output_dir/deps."""
    out_path = Path(output_dir).resolve()
    deps_dir = out_path / "deps"
    deps_dir.mkdir(parents=True, exist_ok=True)
    extracted: List[str] = []

    with _open_bundle_tar(b64_string) as tar:
        for m in tar.getmembers():
            norm_name = (m.name[2:] if m.name.startswith("./") else m.name)
            if norm_name.startswith("deps/") and m.isfile():
                dest_file = out_path / norm_name
                dest_file.parent.mkdir(parents=True, exist_ok=True)
                f = tar.extractfile(m)
                if f is not None:
                    dest_file.write_bytes(f.read())
                    extracted.append(norm_name)
    return extracted


class BundleFinder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    """Imports modules directly from in-memory blztar with shadow fallback for deps/."""

    def __init__(self, b64_string: str, self_mod: Optional[types.ModuleType] = None, on_disk_root: Optional[Path] = None):
        self.b64_string = b64_string
        self.self_mod = self_mod
        self.on_disk_root = on_disk_root
        self._index: dict[str, bytes] = {}
        with _open_bundle_tar(b64_string) as tar:
            for member in tar.getmembers():
                if member.isfile():
                    norm = member.name.lstrip("./")
                    f = tar.extractfile(member)
                    if f is not None:
                        self._index[norm] = f.read()

        self.declared_deps: Set[str] = set()
        gitmodules_data = self._index.get(".gitmodules")
        if self.on_disk_root and (self.on_disk_root / ".gitmodules").is_file():
            try:
                gitmodules_data = (self.on_disk_root / ".gitmodules").read_bytes()
            except Exception:
                pass
        if gitmodules_data:
            text = gitmodules_data.decode("utf-8", errors="ignore")
            for line in text.splitlines():
                m = re.match(r"\s*path\s*=\s*deps/([A-Za-z0-9_.-]+)", line)
                if m:
                    self.declared_deps.add(m.group(1))

    def is_in_git_checkout(self) -> bool:
        if self.on_disk_root:
            return (self.on_disk_root / ".git").exists() or (self.on_disk_root / ".gitmodules").exists()
        return False

    def find_spec(self, fullname: str, path=None, target=None):
        if fullname == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return importlib.machinery.ModuleSpec(
                name=fullname,
                loader=self,
                origin="<dwimsy-bundle>/dwimsy/meta/unbundle.py",
                is_package=False,
            )

        if fullname.startswith("deps.") or fullname == "deps":
            parts = fullname.split(".")
            if len(parts) > 1:
                dep_name = parts[1]
                if self.on_disk_root and (self.on_disk_root / "deps" / dep_name).exists():
                    return None
                if self.is_in_git_checkout() and dep_name not in self.declared_deps:
                    return None

        if not (
            fullname == "dwimsy"
            or fullname.startswith("dwimsy.")
            or fullname == "deps"
            or fullname.startswith("deps.")
        ):
            return None

        rel_base = fullname.replace(".", "/")
        pkg_path = f"{rel_base}/__init__.py"
        mod_path = f"{rel_base}.py"
        dep_pkg_path = f"deps/{rel_base}/__init__.py"
        dep_mod_path = f"deps/{rel_base}.py"

        for candidate, is_pkg in [
            (pkg_path, True),
            (mod_path, False),
            (dep_pkg_path, True),
            (dep_mod_path, False),
        ]:
            if candidate in self._index:
                spec = importlib.machinery.ModuleSpec(
                    name=fullname,
                    loader=self,
                    origin=f"<dwimsy-bundle>/{candidate}",
                    is_package=is_pkg,
                )
                if is_pkg:
                    spec.submodule_search_locations = [f"<dwimsy-bundle>/{rel_base}"]
                return spec
        return None

    def create_module(self, spec):
        if spec.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return self.self_mod
        return None

    def exec_module(self, module: types.ModuleType):
        if module.__spec__.name == "dwimsy.meta.unbundle" and self.self_mod is not None:
            return
        origin = module.__spec__.origin
        if not origin or not origin.startswith("<dwimsy-bundle>/"):
            raise ImportError(f"Cannot execute module from origin {origin}")

        path = origin.removeprefix("<dwimsy-bundle>/")
        source = self._index.get(path)
        if source is None:
            raise ImportError(f"Missing bundled source for {path}")

        code = compile(source, origin, "exec")
        module.__file__ = origin
        exec(code, module.__dict__)


def detect_self_location(argv0_override: Optional[str] = None) -> Tuple[bool, Optional[Path]]:
    """Determine if executing inside a real git checkout with sibling corroboration."""
    if argv0_override:
        candidates = [Path(argv0_override)]
    else:
        candidates = []
        try:
            candidates.append(Path(__file__))
        except NameError:
            pass
        if sys.argv and sys.argv[0]:
            candidates.append(Path(sys.argv[0]))

    for c in candidates:
        try:
            p = c.resolve()
            if p.name in ("unbundle.py", "unbundle.pyc") or (p.name.startswith("unbundle.cpython-") and p.name.endswith(".pyc")):
                if len(p.parts) >= 3 and p.parts[-3] == "dwimsy" and p.parts[-2] == "meta":
                    repo_root = p.parents[2]
                    if (repo_root / "dwimsy" / "_version.py").is_file() and (repo_root / "tests").is_dir():
                        return (True, repo_root)
        except Exception:
            pass
    return (False, None)


UNBUNDLE_PROG_PATTERN = re.compile(
    r"^(?:.*[/\\])?(?:(?:dwimsy[.\-_/ ])?(?:meta[.\-_/ ])?)?unbundle(?:\.py|\.pyz|\.pyc)?(?: |$)",
    re.IGNORECASE,
)


def is_unbundle_invocation(prog_name: Optional[str] = None) -> bool:
    if prog_name is None:
        prog_name = sys.argv[0] if sys.argv else ""
    return bool(UNBUNDLE_PROG_PATTERN.search(prog_name))


def parse_early_pipeline_flags(args: List[str]) -> Tuple[Dict[str, any], List[str]]:
    """Parse early version pipeline flags case-insensitively."""
    pipeline: Dict[str, any] = {
        "argv0": None,
        "include": [],
        "restrict_to": None,
        "prune": None,
        "splice": None,
        "alt": (False, None),
        "version": None,
        "list_versions": False,
    }
    remaining = []
    i = 0
    while i < len(args):
        a = args[i]
        a_lower = a.lower()
        if a_lower in ("-a", "--argv0"):
            if i + 1 < len(args):
                pipeline["argv0"] = args[i + 1]
                i += 2
                continue
            else:
                remaining.append(a)
                i += 1
                continue
        elif a_lower.startswith("--argv0="):
            pipeline["argv0"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower.startswith("-a="):
            pipeline["argv0"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower.startswith("--include="):
            pipeline["include"].append(a.split("=", 1)[1])
            i += 1
            continue
        elif a_lower.startswith("--restrict-to="):
            pipeline["restrict_to"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower.startswith("--prune="):
            pipeline["prune"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower.startswith("--splice="):
            pipeline["splice"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower == "--alt":
            pipeline["alt"] = (True, None)
            i += 1
            continue
        elif a_lower.startswith("--alt="):
            pipeline["alt"] = (True, a.split("=", 1)[1])
            i += 1
            continue
        elif a_lower.startswith("--version="):
            pipeline["version"] = a.split("=", 1)[1]
            i += 1
            continue
        elif a_lower == "--list-versions":
            pipeline["list_versions"] = True
            i += 1
            continue
        else:
            remaining.append(a)
            i += 1
    return pipeline, remaining


def resolve_argv0_command(argv0: str) -> List[str]:
    """Resolve command sequence implied by binary name or -a / --argv0 flag."""
    p = Path(argv0)
    name = p.name
    for ext in (".py", ".pyz", ".pyc", ".exe"):
        if name.lower().endswith(ext):
            name = name[:-len(ext)]
            break

    m = re.match(r"^(.*?)(?:_v?\d+[0-9A-Za-z._+-]*)$", name)
    if m:
        name = m.group(1)

    raw_lower = name.lower().replace("_", "-")
    if raw_lower in ("dwimsy", "dwimsy-bundle", "bundle") or not raw_lower:
        return []

    verb = resolve_multicall_verb(argv0)
    if verb is not None:
        return [verb]

    clean = raw_lower
    for pref in ("dwimsy-", "dwimsy_"):
        if clean.startswith(pref):
            clean = clean[len(pref):]
            break

    meta_subs = {
        "bundle": ["meta", "bundle"],
        "diff": ["meta", "diff"],
        "integrity": ["meta", "integrity"],
        "lint": ["meta", "lint"],
        "version-bump": ["meta", "version-bump"],
        "fetch-deps": ["meta", "fetch-deps"],
        "bundle-fixtures": ["meta", "bundle-fixtures"],
    }
    if clean == "meta":
        return ["meta"]
    if clean.startswith("meta-"):
        sub = clean[5:]
        if sub in meta_subs:
            return meta_subs[sub]
    if raw_lower.startswith("dwimsy-meta-"):
        sub = raw_lower[12:]
        if sub in meta_subs:
            return meta_subs[sub]

    top_commands = {"convert", "inspect", "split", "join", "tests", "readme", "license", "changelog", "help", "charset", "extract", "package", "bridge", "archive", "recover"}
    if clean in top_commands:
        return [clean]

    return []


def resolve_multicall_verb(argv0: str) -> Optional[str]:
    """Resolve applet verb from invoked binary name."""
    name = Path(argv0).name
    for ext in (".py", ".pyz", ".pyc", ".exe"):
        if name.lower().endswith(ext):
            name = name[:-len(ext)]
            break

    m = re.match(r"^(.*?)(?:_v?\d+[0-9A-Za-z._+-]*)$", name)
    if m:
        cand = m.group(1)
        if cand.lower() not in ("meta", "unbundle", "bundle", "version-bump", "diff", "integrity", "lint", "convert", "inspect", "split", "join") and cand.lower().removeprefix("dwimsy-").removeprefix("dwimsy_") in ("t882wav", "wav2t88"):
            name = cand

    for pref in ("dwimsy-", "dwimsy_"):
        if name.lower().startswith(pref):
            name = name[len(pref):]
            break

    verb = name.lower()
    if verb in ("t882wav", "wav2t88"):
        return verb
    return None


def bootstrap_in_memory_cli(argv: Optional[List[str]] = None) -> None:
    """Mount bundle payload and dispatch CLI across Paths A, B, and C."""
    effective_args = sys.argv[1:] if argv is None else list(argv)

    # VersionSpace lives inside the embedded project and therefore cannot be
    # imported until the bundle importer has been installed.  Bootstrap the
    # importer from the current payload first; the effective VersionSpace is
    # then allowed to replace the payload below.
    this_mod = sys.modules.get(__name__)
    if "dwimsy.meta.unbundle" not in sys.modules:
        sys.modules["dwimsy.meta.unbundle"] = this_mod
    if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
        sys.meta_path.insert(0, BundleFinder(_get_active_blztar(), self_mod=this_mod))

    from dwimsy.meta.versions import VersionSpace
    pipeline, remaining_args = parse_early_pipeline_flags(effective_args)

    argv0_effective = pipeline["argv0"] or (sys.argv[0] if sys.argv else "dwimsy")
    is_checkout, repo_root = detect_self_location(pipeline["argv0"])

    raw_b64 = _get_active_blztar()
    vspace = VersionSpace.from_blztar(raw_b64)

    vspace.run_pipeline(
        includes=pipeline["include"],
        restrict_to=pipeline["restrict_to"],
        prune=pipeline["prune"],
        splice=pipeline["splice"],
        alt=pipeline["alt"],
    )

    if pipeline["list_versions"]:
        output = vspace.format_list_versions(on_disk_root=repo_root if is_checkout else None)
        print(output)
        sys.exit(0)

    effective_blztar = vspace.to_blztar()
    ver_sel = pipeline["version"]

    cmd_seq = resolve_argv0_command(argv0_effective)
    if cmd_seq:
        if remaining_args and (remaining_args[0] == "dwimsy" or remaining_args[:len(cmd_seq)] == cmd_seq):
            pass
        else:
            remaining_args = cmd_seq + remaining_args

    if ver_sel is None or ver_sel.lower() in ("baseline", "primary"):
        this_mod = sys.modules.get(__name__)
        sys.modules["dwimsy.meta.unbundle"] = this_mod
        bundle_finder = BundleFinder(effective_blztar, self_mod=this_mod, on_disk_root=repo_root)
        sys.meta_path.insert(0, bundle_finder)

        if argv is not None:
            sys.argv = argv
        else:
            sys.argv = [argv0_effective] + remaining_args

        import dwimsy.cli.__main__ as cli_main
        cli_main.main()
        return

    if ver_sel.lower() == "unbundled":
        if is_checkout and repo_root:
            target_unbundle = repo_root / "dwimsy" / "meta" / "unbundle.py"
            target_b64 = ""
            if target_unbundle.is_file():
                m = _BLZTAR_RE.search(target_unbundle.read_bytes())
                if m:
                    target_b64 = target_unbundle.read_bytes()[m.start("prefix"):m.end("suffix")].decode("ascii")

            if target_b64.strip() == effective_blztar.strip():
                sys.argv = [argv0_effective] + remaining_args
                import dwimsy.cli.__main__ as cli_main
                cli_main.main()
                return
            else:
                with tempfile.TemporaryDirectory() as tmpdir:
                    temp_unbundle = Path(tmpdir) / "unbundle.py"
                    template = elide_blztar_bytes(target_unbundle.read_bytes())
                    temp_unbundle.write_bytes(inject_blztar_bytes(template, effective_blztar))
                    cmd = [sys.executable, str(temp_unbundle), f"--argv0={target_unbundle}"] + remaining_args
                    res = subprocess.run(cmd, cwd=str(repo_root))
                    sys.exit(res.returncode)
        else:
            raise ValueError("No unbundled on-disk version available in current environment")

    res = vspace.resolve_version_ref(ver_sel)
    if res is None:
        raise ValueError(f"Version selector '{ver_sel}' could not be resolved.")

    st, ord_idx, v_ref = res
    with tempfile.TemporaryDirectory() as tmpdir:
        temp_bundle = Path(tmpdir) / f"dwimsy_{v_ref.tag}.py"
        mat_state = st.materialize_layer_state(ord_idx)
        template_bytes = mat_state.get("dwimsy/meta/unbundle.py")
        if not template_bytes:
            template_bytes = elide_blztar_bytes(Path(__file__).read_bytes())
        else:
            template_bytes = elide_blztar_bytes(template_bytes)

        from dwimsy.meta.versions import Stream, Layer
        single_space = VersionSpace([Stream(0, "primary", [Layer(mat_state, is_delta=False, version_tag=v_ref.tag)])])
        temp_bundle.write_bytes(inject_blztar_bytes(template_bytes, single_space.to_blztar()))

        cmd = [sys.executable, str(temp_bundle), f"--argv0={argv0_effective}"] + remaining_args
        res_proc = subprocess.run(cmd)
        sys.exit(res_proc.returncode)


def main(argv: Optional[List[str]] = None) -> int:
    """CLI entrypoint for standalone unbundle script."""
    effective = sys.argv[1:] if argv is None else list(argv)
    pipeline, remaining = parse_early_pipeline_flags(effective)

    if pipeline["list_versions"]:
        from dwimsy.meta.versions import VersionSpace
        raw_b64 = _get_active_blztar()
        vspace = VersionSpace.from_blztar(raw_b64)
        is_checkout, repo_root = detect_self_location(pipeline["argv0"])
        print(vspace.format_list_versions(on_disk_root=repo_root if is_checkout else None))
        return 0

    import argparse
    parser = argparse.ArgumentParser(
        prog=Path(pipeline["argv0"] or (sys.argv[0] if sys.argv else "dwimsy-meta-unbundle")).name,
        description="Extract dwimsy standalone bundle.\nHomepage: https://github.com/f-fix/dwimsy",
    )
    parser.add_argument("-V", "--version", action="version", version=f"%(prog)s {get_bundle_version()}")
    parser.add_argument("-T", "--test", nargs="?", const=True, default=False, help="Run scoped self-tests")
    parser.add_argument("-v", "--verbose", action="count", default=0, help="Increase output verbosity")
    parser.add_argument("--help-all", action="store_true", help="Show full help")
    parser.add_argument("target_directory", nargs="?", default=None, help="Target directory for extraction")
    parser.add_argument("--deps", "-d", action="store_true", help="Also extract deps/")
    args = parser.parse_args(remaining)

    if args.test is not False:
        pattern = [args.test] if isinstance(args.test, str) else ["meta unbundle"]
        this_mod = sys.modules.get(__name__)
        if "dwimsy.meta.unbundle" not in sys.modules:
            sys.modules["dwimsy.meta.unbundle"] = this_mod
        if not any(isinstance(finder, BundleFinder) for finder in sys.meta_path):
            bundle_finder = BundleFinder(_get_active_blztar(), self_mod=this_mod)
            sys.meta_path.insert(0, bundle_finder)
        from dwimsy.tests import run_tests
        return run_tests(pattern, verbose=max(args.verbose, 1))

    if not args.target_directory:
        parser.print_help(sys.stderr)
        return 1

    extract_b64_lzma_tar(_get_active_blztar(), args.target_directory, with_deps=args.deps)
    print(f"Successfully extracted to {args.target_directory}")
    return 0


if __name__ == "__main__":
    pipeline, remaining = parse_early_pipeline_flags(sys.argv[1:])
    argv0_effective = pipeline["argv0"] or (sys.argv[0] if sys.argv else "")
    if is_unbundle_invocation(argv0_effective):
        sys.exit(main())
    else:
        bootstrap_in_memory_cli()
